1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
3	
4	const BASE_PREMIUMS: Record<string, number> = {
5	  sword: 100,
6	  amulet: 60,
7	  staff: 80,
8	  potion: 40,
9	};
10	
11	// Divides rather than multiplying by a rate: `amount * 1.1` introduces
12	// floating-point error that shifts the spec's round-up in MHPCO's favour.
13	const percentOf = (percent: number, amount: number): number => (amount * percent) / 100;
14	
15	export type ScenarioResult = { premium: number };
16	
17	type Item = { type: string };
18	
19	type Scenario = {
20	  steps: { items: Item[] }[];
21	};
22	
23	const premiumForItem = (item: Item): number => BASE_PREMIUMS[item.type];
24	
25	export const runScenario = (scenario: Scenario): { results: ScenarioResult[] } => {
26	  const items = scenario.steps[0].items;
27	  const itemsTotal = items.reduce((total, item) => total + premiumForItem(item), 0);
28	  const firstInsuranceSurcharge = percentOf(FIRST_INSURANCE_SURCHARGE_PERCENT, itemsTotal);
29	  const premium = Math.ceil(itemsTotal + firstInsuranceSurcharge + PROCESSING_FEE);
30	  return { results: [{ premium }] };
31	};
